+    return Response.json({ error: "A valid restaurant ID is required." }, { status: 400, headers });
+  }
+
+  const noPhoto = () => new Response(null, { status: 204, headers });
+  const apiKey = process.env.GOOGLE_MAPS_API_KEY;
+  if (!apiKey) return noPhoto();
